<?php
require dirname(__DIR__).'/app/bootstrap.php';require_permission('customers.view');require dirname(__DIR__).'/app/layout.php';$id=(int)($_GET['id']??0);$c=one('SELECT * FROM customers WHERE id=? AND business_id=?',[$id,bid()]);if(!$c){http_response_code(404);exit('Customer not found.');}$action=can('customers.edit')?'<a class="btn primary" href="customers.php?edit='.$id.'">Edit customer</a>':'';page_start($c['name'],'The details behind a stronger customer relationship.',$action);
?><div class="detail-grid"><section class="panel"><span class="avatar blue"><?= e(initials($c['name'])) ?></span><h2><?= e($c['name']) ?></h2><?= badge($c['status']) ?><p><?= e($c['company']) ?></p><p><?= icon('mail') ?> <?= e($c['email']) ?></p><p><?= icon('phone') ?> <?= e($c['phone']) ?></p><p><?= icon('building') ?> <?= nl2br(e($c['address'])) ?></p><h3>Notes</h3><p><?= nl2br(e($c['notes'])) ?></p><a class="btn" href="customers.php"><?= icon('arrow-left') ?> Customers</a></section><section class="panel"><h2>Customer activity</h2><?php if(can('invoices.view')): $docs=rows("SELECT d.*,(SELECT COALESCE(SUM(amount),0) FROM payments p WHERE p.document_id=d.id AND p.business_id=d.business_id AND p.reversed_at IS NULL) paid FROM documents d WHERE customer_id=? AND business_id=? AND type='invoice' ORDER BY issue_date DESC",[$id,bid()]);$billed=array_sum(array_map(fn($d)=>$d['status']==='Issued'?(float)$d['total']:0,$docs));$paid=array_sum(array_map(fn($d)=>$d['status']==='Issued'?(float)$d['paid']:0,$docs)); ?><div class="kpi-grid customer-kpis"><div class="kpi"><div class="kpi-top">Total billed</div><div class="kpi-value"><?= money($billed) ?></div></div><div class="kpi"><div class="kpi-top">Payments received</div><div class="kpi-value"><?= money($paid) ?></div></div><div class="kpi"><div class="kpi-top">Outstanding</div><div class="kpi-value"><?= money($billed-$paid) ?></div></div></div><h3>Invoices</h3><div class="table-scroll"><table><thead><tr><th>INVOICE</th><th>DATE</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody><?php foreach($docs as $d): ?><tr><td><a href="invoice-view.php?id=<?= $d['id'] ?>"><?= e($d['number']) ?></a></td><td><?= date_label($d['issue_date']) ?></td><td><?= money($d['total']) ?></td><td><?= badge(document_status($d)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if(can('quotations.view')): ?><h3>Quotations</h3><?php foreach(rows("SELECT id,number,status FROM documents WHERE business_id=? AND customer_id=? AND type='quotation' ORDER BY id DESC LIMIT 30",[bid(),$id]) as $q): ?><p><a href="invoice-view.php?id=<?= $q['id'] ?>"><?= e($q['number']) ?></a> <?= badge($q['status']) ?></p><?php endforeach;endif; ?></section></div><?php page_end(); ?>
